<?php require_once __DIR__.'/../../includes/bootstrap.php'; require_role('admin');$id=(int)($_GET['id']??0);$q=$pdo->prepare('SELECT k.*,u.id_user,u.username FROM kegiatan k JOIN users u ON u.id_kegiatan=k.id_kegiatan WHERE k.id_kegiatan=?');$q->execute([$id]);$k=$q->fetch();if(!$k)exit('Kegiatan tidak ditemukan.');$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM petugas WHERE id_petugas=? AND id_kegiatan=? AND deleted_at IS NULL');$s->execute([(int)$_GET['edit'],$id]);$edit=$s->fetch();}page_header('Manajemen Petugas'); ?>
<div class="row g-3"><div class="col-lg-5"><div class="card p-4"><h2 class="h5 fw-bold"><?=$edit?'Edit Petugas':'Tambah Petugas Manual'?></h2><form method="post" action="<?=APP_BASE_URL?>/admin/petugas/save.php"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id_kegiatan" value="<?=$id?>"><input type="hidden" name="id_petugas" value="<?=e((string)($edit['id_petugas']??''))?>"><div class="mb-3"><label class="form-label">Nama Petugas</label><input class="form-control" name="nama_petugas" required maxlength="150" value="<?=e($edit['nama_petugas']??'')?>"></div><div class="mb-3"><label class="form-label">Kecamatan</label><select class="form-select" name="kecamatan" required><option value="">Pilih kecamatan</option><?php foreach(kecamatan_list() as $kc):?><option value="<?=$kc?>" <?=strtoupper($edit['kecamatan']??'')===$kc?'selected':''?>><?=$kc?></option><?php endforeach;?></select></div><button class="btn btn-primary"><?=$edit?'Simpan Perubahan':'Tambah Petugas'?></button><?php if($edit):?> <a class="btn btn-light" href="<?=APP_BASE_URL?>/admin/petugas/index.php?id=<?=$id?>">Batal</a><?php endif;?></form></div><div class="card p-4 mt-3"><h2 class="h5 fw-bold">Upload Excel Petugas</h2><p class="small text-secondary">Kolom wajib: Nama Petugas dan Kecamatan. Sistem menampilkan hasil validasi sebelum menyimpan.</p><form method="post" enctype="multipart/form-data" action="<?=APP_BASE_URL?>/admin/petugas/import.php"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id_kegiatan" value="<?=$id?>"><input class="form-control mb-3" type="file" name="file_excel" accept=".xlsx,.csv" required><button class="btn btn-outline-primary">Periksa & Import</button></form><div class="form-text mt-2">Template: <a href="<?=APP_BASE_URL?>/admin/petugas/template.php?id=<?=$id?>">Download Excel</a>.</div></div></div><div class="col-lg-7"><div class="card p-4"><div class="d-flex justify-content-between"><h2 class="h5 fw-bold">Petugas Terdaftar</h2><a class="btn btn-sm btn-outline-secondary" href="<?=APP_BASE_URL?>/admin/kegiatan/detail.php?id=<?=$id?>">Kembali</a></div><div class="table-responsive"><table class="table"><thead><tr><th>Nama</th><th>Kecamatan</th><th></th></tr></thead><tbody><?php $s=$pdo->prepare('SELECT * FROM petugas WHERE id_kegiatan=? AND deleted_at IS NULL ORDER BY nama_petugas');$s->execute([$id]);foreach($s as $x):?><tr><td><?=e($x['nama_petugas'])?></td><td><?=e($x['kecamatan'])?></td><td><a href="?id=<?=$id?>&edit=<?=$x['id_petugas']?>">Edit</a></td></tr><?php endforeach;?></tbody></table></div></div></div></div><?php page_footer(); ?>
